import numpy as np
from collections import deque
def comps(g):
    g=np.array(g); seen=np.zeros_like(g,bool); out=[]
    for i in range(g.shape[0]):
        for j in range(g.shape[1]):
            if g[i,j] and not seen[i,j]:
                c=g[i,j]; q=deque([(i,j)]); seen[i,j]=1; comp=[]
                while q:
                    x,y=q.popleft(); comp.append((x,y))
                    for dx in(-1,0,1):
                        for dy in(-1,0,1):
                            a,b=x+dx,y+dy
                            if 0<=a<g.shape[0] and 0<=b<g.shape[1] and not seen[a,b] and g[a,b]==c:
                                seen[a,b]=1;q.append((a,b))
                out.append((c,comp))
    return out
