# Extract connected components from demo inputs and outputs to find motif templates
from collections import deque
def comps(g,val):
    seen=set(); out=[]
    H,W=g.shape
    for r in range(H):
        for c in range(W):
            if g[r,c]==val and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny,nx]==val and (ny,nx) not in seen:
                                seen.add((ny,nx)); q.append((ny,nx))
                out.append(cells)
    return out
