def solve(k):
    gi=np.array(G[f'Demo pair {k} input']); ho=np.array(G[f'Demo pair {k} output'])
    H,W=gi.shape
    bg=collections.Counter(gi.flatten()).most_common(1)[0][0]
    # templates = most common components in output, keeping only those also containing a colored fragment in input
    to_=normc(ho,bg); ti=set(normc(gi,bg))
    cnt=collections.Counter(to_)
    tpl=[t for t,n in cnt.most_common() if n>=2]
    print('demo',k,'templates:',tpl)
    out=gi.copy()
    for oc in normc(gi,bg):
        colset={v for _,_,v in oc}
        cands=[]
        for tpl_ in tpl:
            for (a,b,v) in tpl_:
                dy,dx=oc[0][0]-a,oc[0][1]-b
                if v==oc[0][2]:
                    ok=True
                    for (pa,pb,pvv) in tpl_:
                        rr,cc=dy+pa,dx+pb
                        rv=gi[rr,cc]
                        if not (rv==bg or rv==pvv): ok=False;break
                    if ok: cands.append((tpl_,dy,dx))
        if not cands: 
            print('no fit for',oc); continue
        best=max(cands,key=lambda x:-sum(1 for pa,pb,_ in tpl_ in [tpl_] if False), key=lambda x:_ for _ in [0])
        best=max(cands,key=lambda c:(sum(1 for pa,pb,_ in c[0] if False)))
        # score: most template cells on fragment
        best=None;bs=-1
        for tpl_,dy,dx in cands:
            sc=sum(1 for pa,pb,vv in tpl_ if gi[dy+pa,dx+pb]!=bg)
            if sc>bs: bs=sc;best=(tpl_,dy,dx)
        tpl_,dy,dx=best
        for pa,pb,vv in tpl_:
            rr,cc=dy+pa,dx+pb
            if 0<=rr<H and 0<=cc<W and gi[rr,cc]==bg: out[rr,cc]=vv
    return out
