                res.append(cells)
    return res
def norm_shape(c,g):
    mr=min(p[0] for p in c); mc=min(p[1] for p in c)
    return frozenset((y-mr,x-mc,int(g[y,x])) for y,x in c)
def solve(i):
    gi=np.array(G[f'Demo pair {i} input']); ho=np.array(G[f'Demo pair {i} output'])
    H_,W_=gi.shape
    bg=collections.Counter(gi.flatten()).most_common(1)[0][0]
    ocnt=collections.Counter(norm_shape(c_,gi) for c_ in comps_abs(ho,bg))
    icnt=collections.Counter(norm_shape(c_,gi) for c_ in comps_abs(gi,bg))
    tlist=[k for k,v in ocnt.items() if v>icnt.get(k,0)]
    out=gi.copy()
    changed=0
    for comp in comps_abs(gi,bg):
        mr=min(p[0] for p in comp); mc=min(p[1] for p in comp)
        rel=frozenset((y-mr,x-mc,int(gi[y,x])) for y,x in comp)
        fits=[]
        for t in tlist:
            S=set(t)
            for dy in range(-H_,H_+1):
                for dx in range(-W_,W_+1):
                    if all(((a+dy,b+dx),int(vv)) in S for a,b,vv in rel):
                        fits.append((t,(dy,dx)))
        if not fits: continue
        best=max(fits,key=lambda f:len(f[0])+len(f[1]))
        t,(dy,dx)=best
        O=(mr-dy,mc-dx)
        for pa,pb,vv in t:
            rr,cc=O[0]+pa,O[1]+pb
            if 0<=rr<H_ and 0<=cc<W_ and gi[rr,cc]==bg: out[rr,cc]=vv; changed+=1
    return out,changed
